package com.swiftpay.ledger.controller; import com.swiftpay.ledger.entity.LedgerTransaction; import com.swiftpay.ledger.repository.LedgerTransactionRepository; import org.springframework.data.domain.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/users") public class TransactionController {private final LedgerTransactionRepository repo; public TransactionController(LedgerTransactionRepository r){repo=r;} @GetMapping("/{userId}/transactions") Page<LedgerTransaction> list(@PathVariable String userId,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int limit,@RequestParam(required=false)String status){Pageable p=PageRequest.of(Math.max(page,1)-1,Math.min(Math.max(limit,1),100),Sort.by("createdAt").descending());return status==null?repo.findBySenderId(userId,p):repo.findBySenderIdAndStatus(userId,status,p);}}